const queryInput = { key: 'query', label: 'Search description', description: 'Natural-language description of the records to find.', type: 'text', required: true } as const;
const countryInput = { key: 'countries', label: 'Countries', description: 'Optional country filters applied by Monid.', type: 'country-list', required: false } as const;
const textInput = (key: string, label: string, description: string, required = false) => ({ key, label, description, type: 'text' as const, required });
const urlInput = (key: string, label: string, description: string, required = false) => ({ key, label, description, type: 'url' as const, required });
const selectInput = (key: string, label: string, description: string, options: Array<{ label: string; value: string }>, required = false) => ({ key, label, description, type: 'select' as const, options, required });
const wideColumn = (field: string, format?: 'url' | 'number') => ({ name: field, field, ...(format ? { format } : {}), width: 180 });
type GenericTypeSeed = Pick<TableTypeDefinition, 'id' | 'category' | 'name' | 'description' | 'instructions' | 'examplePrompts' | 'requiredInputs' | 'defaultColumns' | 'identity' | 'operations' | 'pagination' | 'status'> & { chaining?: TableTypeDefinition['chaining'] };
function genericType(seed: GenericTypeSeed): TableTypeDefinition {
	return { ...seed, entity: 'records', rowMapping: seed.defaultColumns.map(({ name, field }) => ({ sourceField: field, columnName: name })), chaining: seed.chaining ?? { enabled: false, operations: [] } };
}

