/** Why a definition cannot safely appear in Find rows. Every condition is checked in code, not in its editable text. */
export function tableTypeRunnableError(definition: TableTypeDefinition): string | null {
	if (TABLE_TYPE_BLOCKERS[definition.id]) return TABLE_TYPE_BLOCKERS[definition.id]!;
	const adapter = TABLE_TYPE_ADAPTERS[definition.id];
	if (!adapter || adapter.entity !== definition.entity) return 'No trusted search adapter and row identity are implemented for this table type.';
	if (definition.operations.length !== adapter.operations.length || adapter.operations.some((operation) => !definition.operations.includes(operation))) return 'The selected operations do not match this table type’s trusted Monid adapter.';
	if (definition.pagination.strategy !== adapter.pagination || definition.pagination.maxCalls > adapter.maxCalls) return 'The pagination settings exceed the limits supported by this adapter.';
	if (definition.identity.sourceField !== adapter.identity.sourceField || definition.identity.normalization !== adapter.identity.normalization) return 'The stable row identity does not match the identity supported by this adapter.';
	if (definition.chaining.enabled !== (adapter.chaining.length > 0) || definition.chaining.operations.length !== adapter.chaining.length || adapter.chaining.some((operation, index) => definition.chaining.operations[index] !== operation)) return 'The chaining settings do not exactly match the chaining steps supported by this adapter.';
	if (!definition.requiredInputs.some((input) => input.key === 'query' && input.type === 'text' && input.required)) return 'The search description input is required.';
	if (definition.requiredInputs.some((input) => !adapter.inputKeys.includes(input.key))) return 'This adapter does not validate one or more configured search inputs.';
	if (definition.requiredInputs.some((input) => input.key === 'countries' && input.type !== 'country-list')) return 'Country filters must use the country-list input.';
	if (definition.requiredInputs.some((input) => input.type === 'select' && !input.options?.length)) return 'Select inputs need at least one fixed option.';
	const fields = new Set(adapter.fields as readonly string[]);
	if (definition.rowMapping.some((mapping) => !fields.has(mapping.sourceField)) || definition.defaultColumns.some((column) => !fields.has(column.field))) return 'A result mapping references a field this adapter does not return.';
	if (!definition.rowMapping.some((mapping) => mapping.sourceField === adapter.identity.sourceField)) return 'The stable identity field must be mapped into a default column.';
	return null;
}

export function defaultTableTypeForEntity(entity: EntityKind) {
	return DEFAULT_TABLE_TYPES.find((definition) => definition.entity === entity && ['companies', 'people', 'websites'].includes(definition.id)) ?? DEFAULT_TABLE_TYPES[0]!;
}

export function isRunnableTableType(definition: TableTypeDefinition): boolean {
	return definition.status === 'published' && tableTypeRunnableError(definition) === null;
}

export function tableTypeInputError(definition: TableTypeDefinition, input: { query: string; countries?: string[]; inputs?: Record<string, string> }) {
	for (const required of definition.requiredInputs.filter((item) => item.required)) {
		if (required.key === 'query' && !input.query.trim()) return `${required.label} is required.`;
		if (required.key === 'countries' && !input.countries?.length) return `${required.label} is required.`;
		if (required.key !== 'query' && required.key !== 'countries' && !input.inputs?.[required.key]?.trim()) return `${required.label} is required.`;
	}
	for (const select of definition.requiredInputs.filter((item) => item.type === 'select')) {
		const value = input.inputs?.[select.key]?.trim();
		if (value && !select.options?.some((option) => option.value === value)) return `Choose a valid ${select.label.toLowerCase()}.`;
	}
	if (definition.id === 'yelp-reviews') {
		const url = input.inputs?.['business-url']?.trim();
		if (url) {
			try {
				const parsed = new URL(url);
				if (!['www.yelp.com', 'yelp.com'].includes(parsed.hostname) || !parsed.pathname.startsWith('/biz/')) return 'Enter a valid Yelp business URL.';
			} catch { return 'Enter a valid Yelp business URL.'; }
		} else if (!input.inputs?.location?.trim()) return 'Add the business city or a Yelp business URL so the correct listing can be resolved.';
	}
	if (definition.id === 'local-business-search' && input.inputs?.source === 'yelp' && !input.inputs?.location?.trim()) return 'A city or ZIP code is required for Yelp business search.';
	if (['mobile-app-search', 'mobile-app-reviews'].includes(definition.id) && input.inputs?.country?.trim() && !/^[a-z]{2}$/i.test(input.inputs.country.trim())) return 'Country storefront must be a two-letter country code, such as us.';
	if (definition.id === 'funding-rounds') {
		const inputs = input.inputs ?? {};
		for (const key of ['date-start', 'date-end']) if (inputs[key]?.trim() && !/^\d{4}-\d{2}-\d{2}$/.test(inputs[key]!)) return `${key === 'date-start' ? 'Start' : 'End'} date must use YYYY-MM-DD.`;
		if (inputs['min-size']?.trim() && (!/^\d+(?:\.\d{1,2})?$/.test(inputs['min-size']!) || Number(inputs['min-size']) < 0)) return 'Minimum round size must be a non-negative USD amount.';
		for (const key of ['location-permalink', 'industry-permalink']) if (inputs[key]?.trim() && !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(inputs[key]!)) return `${key === 'location-permalink' ? 'Location' : 'Industry'} must be an exact lowercase Fundable permalink.`;
	}
	if (definition.id === 'mobile-app-reviews' && input.inputs?.['app-id']?.trim()) {
		const id = input.inputs['app-id']!.trim();
		if (input.inputs?.storefront === 'apple' && !/^\d{5,20}$/.test(id)) return 'Apple App IDs must be numeric.';
		if (input.inputs?.storefront === 'google' && !/^[A-Za-z0-9._-]{3,200}$/.test(id)) return 'Enter a valid Google Play package ID.';
	}
	if (['import-export-companies', 'hs-code-activity'].includes(definition.id)) {
		const start = input.inputs?.['date-start']?.trim() ?? '', end = input.inputs?.['date-end']?.trim() ?? '';
		const validDate = (value: string) => /^\d{4}-\d{2}-\d{2}$/.test(value) && !Number.isNaN(Date.parse(`${value}T00:00:00Z`)) && new Date(`${value}T00:00:00Z`).toISOString().startsWith(value);
		if (!validDate(start) || !validDate(end)) return 'Enter a valid start and end date using YYYY-MM-DD.';
		if (end < start) return 'End date must be on or after the start date.';
		const maxEnd = new Date(`${start}T00:00:00Z`);
		maxEnd.setUTCFullYear(maxEnd.getUTCFullYear() + 3);
		if (new Date(`${end}T00:00:00Z`) > maxEnd) return 'The Tendata date window may not exceed three years.';
		for (const key of ['country-origin', 'country-destination']) if (input.inputs?.[key]?.trim() && !/^[A-Z]{3}(?:;[A-Z]{3})*$/i.test(input.inputs[key]!.trim())) return `${key === 'country-origin' ? 'Origin' : 'Destination'} country must use one or more ISO3 codes separated by semicolons.`;
		if (definition.id === 'import-export-companies' && input.inputs?.['hs-code']?.trim() && !/^\d{2,10}$/.test(input.inputs['hs-code']!.trim())) return 'HS code must contain 2–10 digits.';
	}
	if (definition.id === 'amazon-seller-offers' && !/^[A-Z0-9]{10}$/i.test(input.inputs?.asin?.trim() ?? '')) return 'Enter a valid 10-character Amazon ASIN.';
	if (definition.id === 'software-reviews') {
		const source = input.inputs?.source;
		const slug = input.inputs?.['product-slug']?.trim() ?? '';
		const productId = input.inputs?.['product-id']?.trim() ?? '';
		const productName = input.inputs?.['product-name']?.trim() ?? '';
		if (slug && !/^[a-z0-9][a-z0-9-]{0,100}$/i.test(slug)) return 'Product slug may contain letters, numbers, and dashes.';
		if (source === 'capterra' && productId && !/^\d{1,12}$/.test(productId)) return 'Capterra product ID must be numeric.';
		if (source === 'capterra' && Boolean(productId || productName || slug) && (!productId || !productName || slug)) return 'To skip product lookup on Capterra, provide both product ID and product name, and clear the G2 product slug.';
		if (source === 'capterra' && productName.length > 200) return 'Capterra product name must be 200 characters or fewer.';
		if (source === 'g2' && productId) return 'G2 uses a product slug; clear the numeric product ID.';
		if (source === 'g2' && productName.length > 200) return 'Product name must be 200 characters or fewer.';
	}
	return null;
}

export function tableTypePricingNote(id: string) { return TABLE_TYPE_ADAPTERS[id]?.priceNote ?? null; }
export function tableTypeRowLimit(id: string, inputs: Record<string, string> = {}) {
	if (id === 'local-business-search' && inputs.source === 'yelp') return 50;
	if (id === 'software-reviews' && inputs.source === 'g2') return 190;
	return TABLE_TYPE_ADAPTERS[id]?.maxRows ?? 1000;
}
